.ds-preview{font-family:"Instrument Sans",sans-serif;color:var(--forest,#10332e);font-weight:400}.ds-preview button,.ds-preview select{font:inherit;color:inherit}.ds-preview button{cursor:pointer}.ds-preview :where(a){color:inherit;text-decoration:none}.ds-preview a:focus-visible,.ds-preview button:focus-visible,.ds-preview select:focus-visible,.ds-preview summary:focus-visible{outline:3px solid currentColor;outline-offset:6px}.ds-preview .ds-arrow,.ds-preview .ds-glyph{width:24px;height:24px;flex-shrink:0}.ds-action{display:inline-flex;gap:24px;align-items:center;font-weight:600;font-size:19px;line-height:1.3}.ds-action{padding:18px 24px;background:var(--lime,#deef59);color:var(--forest,#10332e);border-radius:4px;position:relative;overflow:hidden;transition:background .25s,color .25s,box-shadow .25s}.ds-action .ds-arrow{transition:transform .3s var(--ease,cubic-bezier(.16,1,.3,1))}.ds-action:hover{background:#ebf798;box-shadow:0 7px 20px #001d191c}.ds-action:hover .ds-arrow{transform:translateX(5px)}.ds-action:active{box-shadow:inset 0 2px 5px #10332e26}.ds-home-hero .ds-action{margin-top:30px}.ds-docs-ending .ds-action{background:var(--forest,#10332e);color:var(--paper,#f3f3dc);margin-top:28px}.ds-docs-ending .ds-action:hover{background:#284d40}.ds-evidence-state .ds-action{margin-top:15px}.ds-home-hero .ds-action{margin-top:25px}
.ds-action{font-size:17px;gap:22px;isolation:isolate}.ds-action{padding:16px 23px;border:1px solid transparent;transition:color var(--t-hover,240ms),border-color var(--t-hover,240ms),box-shadow var(--t-hover,240ms),transform var(--t-press,150ms)}
.ds-action:before{content:'';position:absolute;inset:0;background:#2b5141;transform:translateY(104%);transition:transform 350ms var(--ease,cubic-bezier(.16,1,.3,1));z-index:-1}
.ds-action-label{transition:transform 300ms var(--ease,cubic-bezier(.16,1,.3,1))}.ds-action:hover,.ds-action:focus-visible{background:var(--lime,#deef59);color:var(--paper,#f3f3dc);border-color:var(--lime,#deef59);box-shadow:0 6px 16px #001d1920}.ds-action:hover:before,.ds-action:focus-visible:before{transform:translateY(0)}.ds-action:hover .ds-action-label{transform:translateX(-2px)}.ds-action:active{transform:scale(.975);box-shadow:none}
.ds-docs-ending .ds-action:hover{background:var(--forest,#10332e);color:var(--forest,#10332e);border-color:var(--forest,#10332e)}.ds-docs-ending .ds-action:before{background:var(--paper,#f3f3dc)}.ds-home-hero .ds-action{animation:hero-arrive .5s 130ms var(--ease,cubic-bezier(.16,1,.3,1)) both}@media(prefers-reduced-motion:reduce){.ds-preview *,.ds-preview *:before,.ds-preview *:after{transition-duration:0s!important;animation-duration:0s!important}.ds-preview .ds-action:active,.ds-preview .ds-report-scene:hover .ds-report-sheet{transform:none}} .ds-preview .ds-action,.ds-preview .ds-text-action{font-size:16px}

